select json_object('regexp', name regexp 'a', 'not_like', name not like 'a%', 'not_in', id not in (1, 2), 'not_between', id not between 1 and 2, 'is_false', flag is false, 'is_not_true', flag is not true, 'is_unknown', (email = 'a') is unknown, 'exists', exists (select 1 from posts p where p.user_id = users.id), 'in_sub', id in (select user_id from posts), 'unary_plus', +(id > 0), 'tuple', (id, name) = (1, 'a')) as o from users
